import {initAuth,request,onAuthStateChanged,signOut} from './firebase-client.js';
import {locations as initialLocations} from './data.js';
import {banglaNames} from './i18n.js';
import {apiEnabled} from './config.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let auth=null,me=null,ready=false,tab='overview',loadVersion=0,records=[],buildings=[],sources=[],media=[],editing=null;
const names={overview:'Overview',locations:'Buildings',sources:'Water sources',reports:'Test reports',problems:'Problem reports',media:'Media library',users:'User accounts',audit:'Activity log'};
const statuses={no_growth:'No growth detected in screening',growth_detected:'Growth detected – further assessment needed',pending:'Pending / Not tested',retest_recommended:'Retesting recommended'};
const titles={overview:'A healthier campus starts here.',locations:'Every building, in one place.',sources:'Your campus water directory.',reports:'Evidence behind every drop.',problems:'Review and verify water problems.',media:'A home for your test images.',users:'Manage your community accounts.',audit:'A clear record of every change.'};
const descriptions={overview:'Manage your water sources and the evidence behind every report.',locations:'Create and update campus locations in English and Bangla.',sources:'Manage source codes, buildings, labels, and display order.',reports:'Publish screening outcomes, test dates, and original sample images.',problems:'Verify community problem reports submitted by students and staff before they appear on the public portal.',media:'Upload PNG, JPEG, or WebP images. Up to 5 MB per image.',users:'Create accounts, update names, disable sign-in, or remove accounts. Owner only.',audit:'The latest 200 content and access changes. Entries cannot be edited.'};
function banner(message){$('#setup-banner').hidden=false;$('#setup-banner').textContent=message}
let toastTimer;function toast(m){$('#admin-toast').textContent=m;$('#admin-toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#admin-toast').classList.remove('visible'),4500)}
function errorContent(message){$('#dashboard-content').innerHTML=`<div class="notice error">${esc(message)}</div><button class="secondary" id="retry">Try again</button>`;$('#retry').onclick=()=>loadTab(tab)}
function button(label,action,id='',disabled=false){return `<button class="secondary" data-action="${action}" data-id="${esc(id)}" ${disabled?'disabled':''}>${label}</button>`}
const empty=(title,text)=>`<div class="panel empty-state"><div class="empty-symbol">▤</div><h3>${title}</h3><p>${text}</p></div>`;
function setHeading(){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.tab===tab));$('#crumb').textContent=names[tab];$('#page-title').textContent=titles[tab];$('#page-description').textContent=descriptions[tab];$('#page-actions').innerHTML=['locations','sources','reports'].includes(tab)?`<button class="primary" id="add-record" ${ready?'':'disabled'}>+ ${tab==='locations'?'Add building':tab==='sources'?'Add source':'New report'}</button>`:tab==='overview'?`<button class="secondary" id="export-data" ${ready?'':'disabled'}>Export data ↓</button>`:'';$('#add-record')?.addEventListener('click',()=>openEditor());$('#export-data')?.addEventListener('click',exportData)}
async function loadTab(next){tab=next;const seq=++loadVersion;setHeading();$('#dashboard-content').innerHTML='<p>Loading workspace…</p>';try{
 if(!ready){preview();return}
 if(tab==='overview'){const [counts,ls]=await Promise.all([request('/api/admin/overview'),request('/api/admin/locations')]);if(seq!==loadVersion)return;buildings=ls;overview(counts,ls);return}
 if(tab==='problems'){const r=await request('/api/admin/problem-reports');if(seq!==loadVersion)return;records=r;renderProblems();return}
 if(tab==='users'){if(me.role!=='owner'){$('#dashboard-content').innerHTML=empty('Owner access required','User accounts are managed by the workspace owner.');return}const r=await request('/api/admin/users');if(seq!==loadVersion)return;renderUsers(r);return}
 const r=await request('/api/admin/'+tab);if(seq!==loadVersion)return;records=r;
 if(tab==='media')renderMedia();else if(tab==='audit')renderAudit();else renderTable();
 }catch(e){if(seq===loadVersion)errorContent(e.message)}}
function preview(){const ls=initialLocations.map((l,i)=>({...l,name_bn:banglaNames[l.id],sort_order:i}));if(tab==='overview')overview({buildings:3,sources:24,reports:'—',drafts:'—',pending_problems:0},ls);else if(tab==='locations'){records=ls;renderTable()}else if(tab==='sources'){records=ls.flatMap(l=>l.sources.map(code=>({code,location_id:l.id,label:'',label_bn:''})));renderTable()}else $('#dashboard-content').innerHTML=empty('Connect your workspace','Sign in on the Firebase- and Neon-connected deployment to manage this section.');}
function overview(c,ls){$('#dashboard-content').innerHTML=`<div class="stats-grid">${[['buildings','Campus buildings','⌂'],['sources','Water sources','♧'],['reports','Test reports','▤'],['drafts','Unpublished drafts','◷']].map(([k,label,icon])=>`<div class="stat-card"><span class="stat-symbol">${icon}</span><span class="stat-label">${label}</span><strong>${c[k]??0}</strong><small>${ready?'Your current workspace':'Directory preview'}</small></div>`).join('')}</div>${(c.pending_problems>0)?`<div class="notice" style="margin-bottom:20px;display:flex;justify-content:space-between;align-items:center"><span>⚠ <b>${c.pending_problems} community water problem report(s)</b> awaiting verification.</span><button class="secondary small-button" data-action="go" data-id="problems">Review reports →</button></div>`:''}<div class="overview-grid"><section class="panel"><div class="panel-heading"><div><h3>Campus locations</h3><p>A clear view of the places you monitor.</p></div><button class="link" data-action="go" data-id="locations">Manage →</button></div>${ls.length?ls.map(l=>`<div class="quick-row"><div class="building-symbol">⌂</div><div><h3>${esc(l.name)}</h3><p>${esc(l.name_bn||l.kind)}</p></div></div>`).join(''):'<div class="empty-state"><p>Add your first building to get started.</p></div>'}</section><section class="panel"><div class="panel-heading"><div><h3>Screening, made clear</h3><p>Four outcomes. No assumptions about safety.</p></div></div><div class="status-legend">${Object.entries(statuses).map(([k,v])=>`<div class="status-row"><span class="status-dot ${k}"></span>${v}</div>`).join('')}</div><div class="quick-row"><p>Save reports as drafts while reviewing the evidence, then publish when ready.</p></div></section></div>`;}
function tableRows(list){return list.map(r=>{const id=tab==='sources'?r.code:r.id;let cells='';if(tab==='locations')cells=`<td><strong>${esc(r.name)}</strong><small>${esc(r.name_bn)}</small></td><td>${esc(r.id)}</td><td>${esc(r.kind)}</td><td>${r.sort_order??0}</td>`;if(tab==='sources')cells=`<td><strong>${esc(r.code)}</strong><small>${esc(r.label)}</small></td><td>${esc(r.location_id)}</td><td>${esc(r.label_bn)}</td>`;if(tab==='reports')cells=`<td><strong>${esc(r.source_code)}</strong><small>Report #${esc(r.id)}</small></td><td><span class="badge ${esc(r.screening_status)}">${esc(statuses[r.screening_status]||r.screening_status)}</span></td><td>${esc(r.tested_at?.slice(0,10)||'Not provided')}</td><td><span class="badge ${r.is_published?'':'draft'}">${r.is_published?'Published':'Draft'}</span></td>`;return `<tr>${cells}<td><div class="table-actions"><button data-action="edit" data-id="${esc(id)}" ${ready?'':'disabled'}>Edit</button><button class="delete" data-action="delete" data-id="${esc(id)}" ${ready?'':'disabled'}>Delete</button></div></td></tr>`}).join('')}
function renderTable(){const heads=tab==='locations'?['Building','ID','Type','Order']:tab==='sources'?['Source','Building ID','Bangla label']:['Source','Screening status','Tested','Visibility'];$('#dashboard-content').innerHTML=`<div class="toolbar"><input class="filter-input" id="record-filter" type="search" placeholder="Filter ${names[tab].toLowerCase()}…" aria-label="Filter records"><span class="small">${records.length} records</span></div><div class="panel table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}<th>Actions</th></tr></thead><tbody id="table-body">${tableRows(records)}</tbody></table><div id="table-empty" class="empty-state" ${records.length?'hidden':''}><p>No matching records. Add a record to get started.</p></div></div>`;$('#record-filter').oninput=e=>{const q=e.target.value.toLowerCase();const list=records.filter(r=>Object.values(r).some(v=>String(v).toLowerCase().includes(q)));$('#table-body').innerHTML=tableRows(list);$('#table-empty').hidden=!!list.length}}
function field(key,label,value='',type='text',extra=''){return `<label ${type==='textarea'?'class="full"':''}>${label}${type==='textarea'?`<textarea name="${key}" ${extra}>${esc(value)}</textarea>`:`<input name="${key}" type="${type}" value="${esc(value)}" ${extra}>`}</label>`}
function select(key,label,value,options,extra=''){return `<label>${label}<select name="${key}" ${extra}>${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`}
async function openEditor(id){if(!ready)return;editing=id==null?null:records.find(r=>String(tab==='sources'?r.code:r.id)===String(id));const r=editing||{};try{if(tab==='sources')buildings=await request('/api/admin/locations');if(tab==='reports'){[sources,media]=await Promise.all([request('/api/admin/sources'),request('/api/admin/media')]);if(!sources.length){toast('Create a water source before adding a report.');return}}if(tab==='sources'&&!buildings.length){toast('Create a building before adding a source.');return}
 $('#editor-title').textContent=(editing?'Edit ':'Create ')+(tab==='locations'?'building':tab==='sources'?'water source':'test report');$('#editor-error').textContent='';let fields='';
 if(tab==='locations')fields=field('id','Building ID',r.id||'','text',`required maxlength="80" ${editing?'readonly':''}`)+field('name','Name · English',r.name||'','text','required maxlength="200"')+field('name_bn','Name · বাংলা',r.name_bn||'')+field('kind','Building type',r.kind||'SCHOLAR RESIDENCE')+field('sort_order','Display order',r.sort_order??0,'number','step="1"')+'<p class="field-hint full">Lower display-order values appear first. The building ID stays fixed; names can change anytime.</p>';
 if(tab==='sources')fields=field('code','Source code',r.code||'','text','required maxlength="120"')+select('location_id','Building',r.location_id,buildings.map(l=>[l.id,l.name]))+field('label','Optional label · English',r.label||'')+field('label_bn','Optional label · বাংলা',r.label_bn||'')+field('sort_order','Display order',r.sort_order??0,'number','step="1"')+'<p class="field-hint full">Renaming a source updates its linked reports. Previously shared source-code links will need updating.</p>';
 if(tab==='reports')fields=select('source_code','Water source',r.source_code,sources.map(s=>[s.code,s.code]))+select('screening_status','Screening status',r.screening_status||'pending',Object.entries(statuses))+field('tested_at','Last tested date',r.tested_at?.slice(0,10)||'','date')+field('next_screening_at','Next recommended screening',r.next_screening_at?.slice(0,10)||'','date')+field('sampled_at','Sample collection date',r.sampled_at?.slice(0,10)||'','date')+select('media-choice','Choose an uploaded test image','',[['','Choose from media library…'],...media.map(m=>[m.url,m.filename])])+field('photo_url','Test image URL',r.photo_url||'','text','maxlength="2000"')+'<label>Or upload a new test image<input id="report-image-upload" type="file" accept="image/png,image/jpeg,image/webp"><span class="field-hint">PNG, JPEG or WebP · up to 5 MB</span></label>'+field('laboratory','Laboratory · English',r.laboratory||'')+field('laboratory_bn','Laboratory · বাংলা',r.laboratory_bn||'')+select('coliform_status','Coliform result (optional)',r.coliform_status||'not_tested',[['not_tested','Not tested'],['detected','Detected'],['not_detected','Not detected']])+field('ph','pH',r.ph??'','number','min="0" max="14" step="any"')+field('tds','TDS · mg/L',r.tds??'','number','min="0" step="any"')+field('turbidity','Turbidity · NTU',r.turbidity??'','number','min="0" step="any"')+field('notes','Notes · English',r.notes||'','textarea')+field('notes_bn','Notes · বাংলা',r.notes_bn||'','textarea')+`<label class="check full"><input name="is_published" type="checkbox" ${r.is_published?'checked':''}> Publish this report on the public website</label><p class="field-hint full">New reports are drafts by default. Only publish verified information from your actual test.</p>`;
 $('#editor-fields').innerHTML=fields;$('#editor').showModal();const f=$('#editor-form');f.elements['media-choice']?.addEventListener('change',e=>{if(e.target.value)f.elements.photo_url.value=e.target.value});$('#report-image-upload')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;const b=$('#save-editor');b.disabled=true;try{const m=await upload(file);f.elements.photo_url.value=m.url;toast('Image uploaded. Save the report to attach it.')}catch(e){$('#editor-error').textContent=e.message}finally{b.disabled=false}})
 }catch(e){toast(e.message)}}
$('#editor-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;const body=Object.fromEntries(new FormData(f));delete body['media-choice'];if(tab==='reports'){body.is_published=f.elements.is_published.checked;for(const k of ['ph','tds','turbidity'])body[k]=body[k]===''?null:Number(body[k]);for(const k of ['tested_at','sampled_at','next_screening_at'])body[k]=body[k]||null}else body.sort_order=Number(body.sort_order);if(editing)body.revision=editing.revision;const id=editing&&(tab==='sources'?editing.code:editing.id);$('#save-editor').disabled=true;try{await request('/api/admin/'+tab+(editing?'/'+encodeURIComponent(id):''),{method:editing?'PUT':'POST',body:JSON.stringify(body)});$('#editor').close();toast('Changes saved.');await loadTab(tab)}catch(e){$('#editor-error').textContent=e.message}finally{$('#save-editor').disabled=false}};
$('#close-editor').onclick=$('#cancel-editor').onclick=()=>$('#editor').close();
async function deleteRecord(id,kind=tab){if(!ready)return;const record=records.find(r=>String(kind==='sources'?r.code:r.id)===String(id));const label=kind==='media'?'this image':kind==='users'?'this Firebase account (including its ability to sign in)':kind==='locations'?record?.name:kind==='sources'?record?.code:`report #${id}`;$('#confirm-description').textContent=`You are removing ${label}.`;$('#confirm-dialog').showModal();$('#confirm-delete').onclick=async()=>{$('#confirm-delete').disabled=true;try{await request(`/api/admin/${kind}/${encodeURIComponent(id)}`,{method:'DELETE',body:JSON.stringify(record?.revision?{revision:record.revision}:{})});$('#confirm-dialog').close();toast('Deleted.');await loadTab(tab)}catch(e){$('#confirm-dialog').close();toast(e.message)}finally{$('#confirm-delete').disabled=false}}}
$('#cancel-delete').onclick=()=>$('#confirm-dialog').close();
async function upload(file){if(file.size>5*1024*1024)throw Error('Choose an image smaller than 5 MB.');return request('/api/admin/media',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-File-Name':encodeURIComponent(file.name)},body:file})}
function renderMedia(){$('#dashboard-content').innerHTML=`<div class="upload-box"><h3>Keep the full picture.</h3><p>Images are stored in your Neon database, so they survive hosting restarts. Original sample labels stay visible.</p><input id="media-upload" type="file" accept="image/png,image/jpeg,image/webp" aria-label="Upload test image"></div>${records.length?`<div class="media-grid">${records.map(m=>`<article class="media-card"><a href="${esc(m.url)}" target="_blank" rel="noopener"><img src="${esc(m.url)}" alt="${esc(m.filename)}" loading="lazy"></a><div><p>${esc(m.filename)} · ${(m.size/1024).toFixed(0)} KB</p><div class="table-actions"><button data-action="copy-image" data-id="${esc(m.url)}">Copy URL</button><button class="delete" data-action="delete-media" data-id="${esc(m.id)}">Delete</button></div></div></article>`).join('')}</div>`:empty('No images yet','Upload a sample image, then attach it to a test report.')}`;$('#media-upload').onchange=async e=>{const file=e.target.files[0];if(!file)return;e.target.disabled=true;try{await upload(file);toast('Image uploaded.');await loadTab('media')}catch(err){toast(err.message);e.target.disabled=false}}}
function renderAudit(){$('#dashboard-content').innerHTML=records.length?`<div class="panel table-wrap"><table><thead><tr><th>When</th><th>Who</th><th>Action</th><th>Record</th></tr></thead><tbody>${records.map(r=>`<tr><td>${esc(new Date(r.created_at).toLocaleString())}</td><td>${esc(r.actor_email||r.actor_uid)}</td><td>${esc(r.action)}</td><td>${esc(r.entity)}<small>${esc(r.entity_id)}</small></td></tr>`).join('')}</tbody></table></div>`:empty('No changes recorded yet','Saved changes and administrator access changes will appear here.')}
function renderProblems(){const labels={unusual_colour:'Unusual colour',odour:'Odour / Smell',visible_particles:'Visible particles',suspected_contamination:'Suspected contamination'};const pRows=list=>list.map(r=>{let actions='';if(r.status==='pending'){actions+=button('Verify','verify-problem',r.id);actions+=button('Reject','reject-problem',r.id)}else if(r.status==='verified'){actions+=button('Unverify','reset-problem',r.id);actions+=button('Reject','reject-problem',r.id)}else if(r.status==='rejected'){actions+=button('Verify','verify-problem',r.id);actions+=button('Reset to pending','reset-problem',r.id)}actions+=`<button class="delete" data-action="delete-problem" data-id="${esc(r.id)}">Delete</button>`;return `<tr><td><small>${esc(new Date(r.created_at).toLocaleString())}</small></td><td><strong>${esc(r.reporter_name)}</strong><small>${esc(r.reporter_id)}</small></td><td><strong>${esc(r.location_or_source)}</strong></td><td><span class="badge ${esc(r.problem_type)}">${esc(labels[r.problem_type]||r.problem_type)}</span></td><td style="max-width:240px;overflow-wrap:anywhere">${esc(r.description||'—')}</td><td><span class="badge ${r.status==='verified'?'no_growth':r.status==='rejected'?'growth_detected':'pending'}">${esc(r.status.toUpperCase())}</span></td><td><div class="table-actions">${actions}</div></td></tr>`}).join('');$('#dashboard-content').innerHTML=`<div class="toolbar"><input class="filter-input" id="problem-filter" type="search" placeholder="Filter problem reports…" aria-label="Filter problems"><span class="small">${records.length} reports</span></div><div class="panel table-wrap"><table><thead><tr><th>Date</th><th>Reporter</th><th>Location / Source</th><th>Problem Type</th><th>Description</th><th>Status</th><th>Actions</th></tr></thead><tbody id="problems-table-body">${pRows(records)}</tbody></table><div id="problems-empty" class="empty-state" ${records.length?'hidden':''}><p>No problem reports submitted yet.</p></div></div>`;$('#problem-filter').oninput=e=>{const q=e.target.value.toLowerCase();const list=records.filter(r=>Object.values(r).some(v=>String(v).toLowerCase().includes(q)));$('#problems-table-body').innerHTML=pRows(list);$('#problems-empty').hidden=!!list.length};}
async function exportData(){try{const data=await request('/api/admin/export');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='aquavita-records-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Records exported. Images can be downloaded from Media.')}catch(e){toast(e.message)}}
$('#dashboard-content').onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;if(action==='go')loadTab(id);if(action==='edit')openEditor(id);if(action==='delete')deleteRecord(id);if(action==='delete-media')deleteRecord(id,'media');if(action==='delete-user')deleteRecord(id,'users');if(action==='edit-user')editUser(id);if(action==='verify-problem'){try{await request(`/api/admin/problem-reports/${encodeURIComponent(id)}/verify`,{method:'PUT',body:JSON.stringify({status:'verified'})});toast('Problem report verified and published.');await loadTab('problems')}catch(e){toast(e.message)}}if(action==='reject-problem'){try{await request(`/api/admin/problem-reports/${encodeURIComponent(id)}/verify`,{method:'PUT',body:JSON.stringify({status:'rejected'})});toast('Problem report rejected.');await loadTab('problems')}catch(e){toast(e.message)}}if(action==='reset-problem'){try{await request(`/api/admin/problem-reports/${encodeURIComponent(id)}/verify`,{method:'PUT',body:JSON.stringify({status:'pending'})});toast('Problem report reset to pending.');await loadTab('problems')}catch(e){toast(e.message)}}if(action==='delete-problem'){$('#confirm-description').textContent='You are removing this problem report.';$('#confirm-dialog').showModal();$('#confirm-delete').onclick=async()=>{$('#confirm-delete').disabled=true;try{await request(`/api/admin/problem-reports/${encodeURIComponent(id)}`,{method:'DELETE'});$('#confirm-dialog').close();toast('Report deleted.');await loadTab('problems')}catch(e){$('#confirm-dialog').close();toast(e.message)}finally{$('#confirm-delete').disabled=false}};}if(action==='copy-image'){try{await navigator.clipboard.writeText(id);toast('Image URL copied.')}catch{toast('Open the image and copy its address.')}}};
$('#admin-nav').onclick=e=>{const b=e.target.closest('[data-tab]');if(b)loadTab(b.dataset.tab)};
$('#logout').onclick=async()=>{await signOut(auth);location.href='/login.html'};
if(!apiEnabled){banner('Preview only — Firebase and Neon are not connected here. Deploy the Node.js project to Render to enable sign-in and editing.');$('#user-email').textContent='Preview';loadTab('overview')}else{try{auth=await initAuth();onAuthStateChanged(auth,async user=>{loadVersion++;ready=false;me=null;records=[];$('#dashboard-content').textContent='Checking account access…';if(!user){location.replace('/login.html');return}try{me=await request('/api/me');if(!['owner','admin'].includes(me.role)){banner('This account does not have admin access. Ask the owner to add your Firebase UID: '+me.uid);$('#user-email').textContent=me.email;$('#logout').hidden=false;$('#sign-in-link').hidden=true;$('#dashboard-content').innerHTML=empty('Administrator access required','Your account is signed in, but does not have editing permissions.');return}ready=true;$('#setup-banner').hidden=true;$('#user-email').textContent=me.email;$('#logout').hidden=false;$('#sign-in-link').hidden=true;loadTab(tab)}catch(e){banner(e.message);$('#user-email').textContent=user.email;$('#logout').hidden=false;$('#dashboard-content').innerHTML=empty('Account verification required','Open your account page to verify your email, then try again.')}})}catch(e){banner(e.message);$('#user-email').textContent='Setup required';loadTab('overview')}}

let userAccounts=[],nextUserPage=null;
function renderUsers(data,append=false){userAccounts=append?[...userAccounts,...data.users]:data.users;nextUserPage=data.nextPageToken;$('#dashboard-content').innerHTML=`<div class="panel settings-panel"><h3>Create an account</h3><p class="small" style="margin:10px 0 20px">Created accounts must verify their email and have admin access granted separately. No email is sent by this form.</p><form id="create-user" class="form-grid">${field('displayName','Full name','','text','required maxlength="100"')}${field('email','Email address','','email','required')}${field('password','Temporary password','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}<div class="full"><button class="primary">Create account</button></div></form></div><div class="panel table-wrap" style="margin-top:20px"><table><thead><tr><th>Account</th><th>Email status</th><th>Sign-in</th><th>Actions</th></tr></thead><tbody>${userAccounts.map(u=>`<tr><td><strong>${esc(u.email)}</strong><small>${esc(u.displayName)} · ${esc(u.uid)}</small></td><td>${u.emailVerified?'Verified':'Unverified'}</td><td>${u.disabled?'Disabled':'Enabled'}</td><td><div class="table-actions">${button('Edit','edit-user',u.uid,u.uid===me.uid)}${button('Delete','delete-user',u.uid,u.uid===me.uid)}</div></td></tr>`).join('')}</tbody></table></div>${nextUserPage?'<button id="load-users" class="secondary" style="margin-top:16px">Load more accounts</button>':''}`;$('#create-user').onsubmit=async e=>{e.preventDefault();const b=e.currentTarget.querySelector('button');b.disabled=true;try{await request('/api/admin/users',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});toast('Account created. The user can sign in and request a verification email.');await loadTab('users')}catch(e){toast(e.message);b.disabled=false}};$('#load-users')?.addEventListener('click',async()=>{try{const r=await request('/api/admin/users?page='+encodeURIComponent(nextUserPage));renderUsers(r,true)}catch(e){toast(e.message)}})}
function editUser(uid){const u=userAccounts.find(u=>u.uid===uid);if(!u)return;$('#editor-title').textContent='Edit user account';$('#editor-error').textContent='';$('#editor-fields').innerHTML=field('displayName','Full name',u.displayName,'text','maxlength="100"')+`<label class="check full"><input type="checkbox" name="disabled" ${u.disabled?'checked':''}> Disable this account’s sign-in</label><p class="field-hint full">Email: ${esc(u.email)}. Use Firebase Console for email-address changes.</p>`;$('#editor').showModal();}
const saveContentForm=$('#editor-form').onsubmit;
// Store the UID separately so a changed display name never changes the target account.
let editingUserUid=null;
const originalEditUser=editUser;
editUser=uid=>{editingUserUid=uid;originalEditUser(uid)};
$('#editor-form').onsubmit=async e=>{if(tab!=='users')return saveContentForm(e);e.preventDefault();$('#save-editor').disabled=true;try{await request('/api/admin/users/'+encodeURIComponent(editingUserUid),{method:'PUT',body:JSON.stringify({displayName:e.currentTarget.elements.displayName.value,disabled:e.currentTarget.elements.disabled.checked})});$('#editor').close();toast('Account updated.');await loadTab('users')}catch(e){$('#editor-error').textContent=e.message}finally{$('#save-editor').disabled=false}};
